[
    {
        "title": "画图取点",
        "description": "由题意知，剩余油量 $y$ 与行驶时间 $x$ 成一次函数关系，且图象经过两点 $A(2,48)$、$B(5,30)$。",
        "bubbleText": "把“2小时48升”和“5小时30升”先看成坐标平面上的两个点。",
        "bubblePos": {
            "x": 400.0,
            "y": 300.0
        },
        "arrowTarget": {
            "x": 420.0,
            "y": 333.0
        }
    },
    {
        "title": "求斜率",
        "description": "设一次函数为 $y=kx+b$。由两点斜率公式，$k=\\dfrac{30-48}{5-2}=-6$，表示每行驶 $1$ 小时少 $6$ 升油。",
        "bubbleText": "剩余油量减少了 $18$ 升，用了 $3$ 小时，所以每小时减少 $6$ 升。",
        "bubblePos": {
            "x": 400.0,
            "y": 300.0
        },
        "arrowTarget": {
            "x": 420.0,
            "y": 333.0
        }
    },
    {
        "title": "代入求参",
        "description": "把 $k=-6$ 代入 $y=kx+b$，得 $y=-6x+b$。再把点 $A(2,48)$ 代入，得 $48=-6\\times2+b$，解得 $b=60$。",
        "bubbleText": "求初始油量就是求截距 $b$，代入一个已知点就能算出。",
        "bubblePos": {
            "x": 400.0,
            "y": 300.0
        },
        "arrowTarget": {
            "x": 210.0,
            "y": 270.0
        }
    },
    {
        "title": "求初值",
        "description": "因此一次函数解析式为 $y=-6x+60$。加满油时还未行驶，即 $x=0$，所以 $y=-6\\times0+60=60$。",
        "bubbleText": "出发前对应 $x=0$，图象在 $y$ 轴上的截距就是加满时的油量。",
        "bubblePos": {
            "x": 400.0,
            "y": 300.0
        },
        "arrowTarget": {
            "x": 210.0,
            "y": 270.0
        }
    },
    {
        "title": "检验作答",
        "description": "检验：当 $x=2$ 时，$y=60-12=48$；当 $x=5$ 时，$y=60-30=30$，均与题意相符。答：这辆汽车加满油时油箱中有 $60$ 升油。",
        "bubbleText": "把结果代回两个已知时刻都对，说明答案可靠。",
        "bubblePos": {
            "x": 400.0,
            "y": 300.0
        },
        "arrowTarget": {
            "x": 420.0,
            "y": 333.0
        }
    }
]
